import React, { useEffect, useMemo, useRef, useState } from "react";
import "../styles/battle.css";
import { cards } from "../data/cards";

/* 勝敗画像 */
const WIN_IMG  = "/images/win.png";
const LOSE_IMG = "/images/lose.png";

/* ========= 共通ユーティリティ ========= */
function getAvailableReductionsFromBoard(zones) {
  const sum = { red: 0, blue: 0, green: 0, white: 0, yellow: 0, purple: 0 };
  for (const z of zones) {
    if (!z || !z.card) continue;
    const { symbolColor, symbolCount = 1 } = z.card;
    if (symbolCount > 0) sum[symbolColor] = (sum[symbolColor] || 0) + symbolCount;
  }
  return sum;
}
function calcActualCost(card, reductions) {
  let reduce = 0;
  for (const color of Object.keys(card.reduction || {})) {
    const need = card.reduction[color] || 0;
    const have = reductions[color] || 0;
    reduce += Math.min(need, have);
  }
  return Math.max(0, (card.cost || 0) - reduce);
}
function levelFromCores(card, cores) {
  if (!card || !card.levels || card.levels.length === 0) return { lv: 0, core: 0, bp: 0 };
  let current = card.levels[0];
  for (const lvInfo of card.levels) if (cores >= lvInfo.core) current = lvInfo;
  return current;
}
function getBP(z) {
  return levelFromCores(z.card, z.cores).bp || 0;
}
/* 攻撃時BP（ドラグロン Lv1/2 +2000） */
function getAttackBP(z) {
  let bp = getBP(z);
  if (z.card?.id === "draguron-001") {
    const lv = levelFromCores(z.card, z.cores).lv;
    if (lv === 1 || lv === 2) bp += 2000;
  }
  return bp;
}
/* ジークの強制ブロック（相手に回復状態のスピリットが居る時のみ・ネクサス除外） */
function mustForceBlock(attackingZone, defenderZones) {
  const c = attackingZone?.card;
  if (!c || c.type !== "spirit" || c.id !== "siegwurm-001") return false;
  const lv = levelFromCores(c, attackingZone.cores).lv;
  const hasReadySpirit = defenderZones.some(z => z && !z.exhausted && z.card.type === "spirit");
  return hasReadySpirit && (lv === 1 || lv === 2 || lv === 3);
}

/* ========= AI（簡易） ========= */
function evalSide(side) {
  let s = 0;
  for (const z of side.zones) {
    if (!z) continue;
    const lv = levelFromCores(z.card, z.cores);
    s += (lv.bp || 0) / 1000 + (z.card.symbolCount || 0) * 2;
  }
  s += side.reserve * 0.3 + side.life * 5;
  return s;
}
function evaluate(state) {
  return evalSide(state.op) - evalSide(state.me);
}
function simulateMain(state, move) {
  const c = structuredClone(state);
  const you = c.op;
  switch (move.type) {
    case "SUMMON": {
      const card = c.opHand[move.handIndex];
      you.reserve -= move.pay.totalPay;
      you.trash += move.pay.actualCost;
      you.zones[move.zoneIndex] = { card, cores: move.pay.needCores, exhausted: card.type !== "spirit" };
      c.opHand.splice(move.handIndex, 1);
      break;
    }
    case "CORE_ADD": {
      const z = you.zones[move.zoneIndex];
      if (z && you.reserve > 0) { z.cores = (z.cores || 0) + 1; you.reserve -= 1; }
      break;
    }
    default: break;
  }
  return c;
}
function generateLegalMainMoves(state) {
  const moves = [];
  const you = state.op;
  const emptyIdx = you.zones.map((z, i) => (z ? null : i)).filter((i) => i !== null);
  const reductions = getAvailableReductionsFromBoard(you.zones);
  state.opHand.forEach((card, handIndex) => {
    if (card.type === "magic") return;
    const actualCost = calcActualCost(card, reductions);
    const needCores = card.levels?.[0]?.core ?? 0;
    const totalPay = actualCost + needCores;
    if (you.reserve >= totalPay) {
      for (const zoneIndex of emptyIdx) {
        moves.push({ type: "SUMMON", handIndex, zoneIndex, pay: { actualCost, needCores, totalPay } });
      }
    }
  });
  you.zones.forEach((z, zoneIndex) => {
    if (!z) return;
    if (you.reserve > 0) moves.push({ type: "CORE_ADD", zoneIndex });
  });
  return moves;
}
function chooseBestMainMove(state) {
  const legal = generateLegalMainMoves(state);
  if (legal.length === 0) return null;
  let best = null, bestScore = -Infinity;
  for (const mv of legal) {
    const sc = evaluate(simulateMain(state, mv));
    if (sc > bestScore) { bestScore = sc; best = mv; }
  }
  return best;
}

/* =================== 本体 =================== */
export default function Battle() {
  /* 各カード3枚のデッキを作成してシャッフル */
  const fullDeck = useMemo(() => {
    const pile = [];
    for (const c of cards) for (let i = 0; i < 3; i++) pile.push({ ...c, _copy: i + 1 });
    for (let i = pile.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [pile[i], pile[j]] = [pile[j], pile[i]]; }
    return pile;
  }, []);

  const [me, setMe] = useState({ life: 3, reserve: 4, trash: 0, zones: [null, null, null, null], cTrash: [] });
  const [op, setOp] = useState({ life: 3, reserve: 4, trash: 0, zones: [null, null, null, null], cTrash: [] });

  const [deck, setDeck] = useState([]);    // 自分の山
  const [hand, setHand] = useState([]);    // 自分の手
  const [opDeck, setOpDeck] = useState([]);// AIの山
  const [opHand, setOpHand] = useState([]);// AIの手

  const [phase, setPhase] = useState(0);   // 0..4
  const [selectedHandIndex, setSelectedHandIndex] = useState(null);
  const [aiLog, setAiLog] = useState([]);
  const [gameOver, setGameOver] = useState(null);

  // モーダル類
  const [blockPrompt, setBlockPrompt] = useState(null);   // {defender, attackerSide, attackerZone, attacker, attackerBP, attackerSymbols, forced}
  const [flashPrompt, setFlashPrompt] = useState(null);   // {attacker, blocker, atkBP, blkBP, msg, onUse, onPass}
  const [coreMovePrompt, setCoreMovePrompt] = useState(null); // {owner:'me'|'op', cores:number}

  // 攻撃回数（霊峰Lv2の「最初の攻撃後リフレッシュ」判定用）
  const [myAttackCount, setMyAttackCount] = useState(0);

  // 参照
  const meRef = useRef(me), opRef = useRef(op);
  useEffect(() => { meRef.current = me; }, [me]);
  useEffect(() => { opRef.current = op; }, [op]);

  // 初期ドロー：各4枚（山は別々）
  useEffect(() => {
    const d1 = [...fullDeck], d2 = [...fullDeck];
    const drawN = (d, n) => { const out = []; for (let i = 0; i < n && d.length; i++) out.push(d.pop()); return [out, d]; };
    const [m4, nd1] = drawN(d1, 4);
    const [o4, nd2] = drawN(d2, 4);
    setDeck(nd1); setHand(m4);
    setOpDeck(nd2); setOpHand(o4);
  }, [fullDeck]);

  // 勝敗
  useEffect(() => { if (!gameOver && op.life === 0) setGameOver("win"); }, [op.life, gameOver]);
  useEffect(() => { if (!gameOver && me.life === 0) setGameOver("lose"); }, [me.life, gameOver]);

  /* ========== 共通ヘルパ ========== */
  const moveCoresToReserve = (owner, amount) => {
    if (amount <= 0) return;
    if (owner === "me") setMe(m => ({ ...m, reserve: m.reserve + amount }));
    else setOp(o => ({ ...o, reserve: o.reserve + amount }));
  };
  const hasDeityLv = (owner, needLv) => {
    const side = owner === "me" ? meRef.current : opRef.current;
    return side.zones.some(z => z && z.card.id === "deity-001" && levelFromCores(z.card, z.cores).lv >= needLv);
  };
  // 霊峰Lv1：ジーク破壊時のコア行き先選択（★owner側に表示・処理）
  const openCoreMovePrompt = (owner, cores) => {
    const side = owner === "me" ? meRef.current : opRef.current;
    const spiritExists = side.zones.some(z => z && z.card.type === "spirit");
    if (!spiritExists) { moveCoresToReserve(owner, cores); return; }
    setCoreMovePrompt({ owner, cores });
  };
  // 破壊（霊峰トリガー込み）★ownerを正しく引き回す
  const destroySpiritWithTriggers = (owner, zoneIndex) => {
    const side = owner === "me" ? meRef.current : opRef.current;
    const z = side.zones[zoneIndex]; if (!z) return;
    const destroyedCard = z.card;
    const destroyedCores = z.cores || 0;

    // ゾーンから外す（以後 z を直接参照しない）
    if (owner === "me") {
      setMe(m => ({ ...m, zones: m.zones.map((zz,i)=>(i===zoneIndex?null:zz)), cTrash:[...m.cTrash, destroyedCard] }));
    } else {
      setOp(o => ({ ...o, zones: o.zones.map((zz,i)=>(i===zoneIndex?null:zz)), cTrash:[...o.cTrash, destroyedCard] }));
    }

    if (destroyedCard.id === "siegwurm-001" && hasDeityLv(owner, 1)) {
      openCoreMovePrompt(owner, destroyedCores);  // ★相手のジークなら owner='op'
    } else {
      moveCoresToReserve(owner, destroyedCores);
    }
  };
  const markExhausted = (owner, zoneIndex) => {
    const set = owner === "me" ? setMe : setOp;
    set(s => ({ ...s, zones: s.zones.map((z,i)=>(i===zoneIndex&&z?{...z, exhausted:true}:z)) }));
  };
  const applyUnblockedDamage = (defender, symbols, attackerSide, attackerZone, opts = {}) => {
    if (defender === "op") {
      setOp(o => { const newLife = Math.max(0, o.life - symbols); return { ...o, life: newLife, reserve: o.reserve + (o.life - newLife) }; });
    } else {
      setMe(m => { const newLife = Math.max(0, m.life - symbols); return { ...m, life: newLife, reserve: m.reserve + (m.life - newLife) }; });
    }
    if (!opts.noExhaust) markExhausted(attackerSide, attackerZone);
  };
  const resolveBattle = (attackerSide, attackerZone, blockerZone, attackerBPOv, blockerBPOv) => {
    const atkOwner = attackerSide;
    const defOwner = attackerSide === "me" ? "op" : "me";
    const atkState = atkOwner === "me" ? meRef.current : opRef.current;
    const defState = defOwner === "me" ? meRef.current : opRef.current;
    const atkZ = atkState.zones[attackerZone];
    const blkZ = defState.zones[blockerZone];
    if (!atkZ || !blkZ) {
      if (atkZ) markExhausted(attackerSide, attackerZone);
      if (blkZ) markExhausted(defOwner, blockerZone);
      return { attackerAlive: !!atkZ, blockerAlive: !!blkZ };
    }
    const atkBP = typeof attackerBPOv === "number" ? attackerBPOv : getBP(atkZ);
    const blkBP = typeof blockerBPOv === "number" ? blockerBPOv : getBP(blkZ);
    const atkDestroyed = blkBP >= atkBP;
    const blkDestroyed = atkBP >= blkBP;
    markExhausted(defOwner, blockerZone);
    markExhausted(attackerSide, attackerZone);
    if (atkDestroyed) destroySpiritWithTriggers(atkOwner, attackerZone);
    if (blkDestroyed) destroySpiritWithTriggers(defOwner, blockerZone);
    return { attackerAlive: !atkDestroyed, blockerAlive: !blkDestroyed };
  };

  /* ========== フラッシュ（ダブルドローのみ） ========== */
  async function runFlashWindow(attackerSide, attackerZone, blockerZone, baseAtkBP, baseBlkBP) {
    let atkBP = baseAtkBP;
    let blkBP = baseBlkBP;

    const atkState = attackerSide === "me" ? meRef.current : opRef.current;
    const defState = attackerSide === "me" ? opRef.current : meRef.current;
    const attackerCard = atkState.zones[attackerZone]?.card || null;
    const blockerCard  = blockerZone !== null ? defState.zones[blockerZone]?.card || null : null;

    // Defender first
    if (blockerZone !== null) {
      if (attackerSide === "me") {
        // AI側が防御
        const hasDD = opHand.some(c => c.id === "double-draw-001");
        const red = getAvailableReductionsFromBoard(opRef.current.zones);
        const cost = calcActualCost({ id:"double-draw-001", cost:4, reduction:{ red:2 } }, red);
        if (hasDD && opRef.current.reserve >= cost && blkBP < atkBP && atkBP - blkBP <= 2000) {
          blkBP += 2000;
          setOp(o => ({ ...o, reserve:o.reserve-cost, trash:o.trash+cost, cTrash:[...o.cTrash, {id:"double-draw-001", name:"ダブルドロー"}] }));
          setOpHand(h => { const idx=h.findIndex(c=>c.id==="double-draw-001"); if(idx>=0){ const nh=[...h]; nh.splice(idx,1); return nh; } return h; });
          setAiLog(l => [...l, "AIフラッシュ：ダブルドロー(+2000)"]);
        }
      } else {
        // プレイヤーが防御
        const playable = hand.some(c => c.id === "double-draw-001");
        const red = getAvailableReductionsFromBoard(meRef.current.zones);
        const cost = calcActualCost({ id:"double-draw-001", cost:4, reduction:{ red:2 } }, red);
        if (playable) {
          const willUse = await new Promise(res => {
            setFlashPrompt({
              attacker: attackerCard, blocker: blockerCard, atkBP, blkBP,
              msg: `フラッシュ（防御側）：ダブルドローでブロック側BP+2000（必要コア${cost}）を使いますか？`,
              onUse: () => res(true), onPass: () => res(false),
            });
          });
          setFlashPrompt(null);
          if (willUse && meRef.current.reserve >= cost) {
            blkBP += 2000;
            setMe(m => ({ ...m, reserve:m.reserve-cost, trash:m.trash+cost, cTrash:[...m.cTrash, {id:"double-draw-001", name:"ダブルドロー"}] }));
            setHand(h => { const idx=h.findIndex(c=>c.id==="double-draw-001"); if(idx>=0){ const nh=[...h]; nh.splice(idx,1); return nh; } return h; });
          }
        }
      }
    }
    // Attacker second
    if (blockerZone !== null) {
      if (attackerSide === "me") {
        const playable = hand.some(c => c.id === "double-draw-001");
        const red = getAvailableReductionsFromBoard(meRef.current.zones);
        const cost = calcActualCost({ id:"double-draw-001", cost:4, reduction:{ red:2 } }, red);
        if (playable) {
          const willUse = await new Promise(res => {
            setFlashPrompt({
              attacker: attackerCard, blocker: blockerCard, atkBP, blkBP,
              msg: `フラッシュ（攻撃側）：ダブルドローで攻撃側BP+2000（必要コア${cost}）を使いますか？`,
              onUse: () => res(true), onPass: () => res(false),
            });
          });
          setFlashPrompt(null);
          if (willUse && meRef.current.reserve >= cost) {
            atkBP += 2000;
            setMe(m => ({ ...m, reserve:m.reserve-cost, trash:m.trash+cost, cTrash:[...m.cTrash, {id:"double-draw-001", name:"ダブルドロー"}] }));
            setHand(h => { const idx=h.findIndex(c=>c.id==="double-draw-001"); if(idx>=0){ const nh=[...h]; nh.splice(idx,1); return nh; } return h; });
          }
        }
      } else {
        const hasDD = opHand.some(c => c.id === "double-draw-001");
        const red = getAvailableReductionsFromBoard(opRef.current.zones);
        const cost = calcActualCost({ id:"double-draw-001", cost:4, reduction:{ red:2 } }, red);
        if (hasDD && opRef.current.reserve >= cost && atkBP <= blkBP && blkBP - atkBP <= 2000) {
          atkBP += 2000;
          setOp(o => ({ ...o, reserve:o.reserve-cost, trash:o.trash+cost, cTrash:[...o.cTrash, {id:"double-draw-001", name:"ダブルドロー"}] }));
          setOpHand(h => { const idx=h.findIndex(c=>c.id==="double-draw-001"); if(idx>=0){ const nh=[...h]; nh.splice(idx,1); return nh; } return h; });
          setAiLog(l => [...l, "AIフラッシュ：ダブルドロー(+2000)"]);
        }
      }
    }
    return { atkBP, blkBP };
  }

  /* ========== 自分の操作 ========== */
  const canSummon = phase === 3;
  const canAttack = phase === 4;

  // 二重クリック防止ロック
  const stepLockRef = useRef(false);
  const castLockRef = useRef(false);

  const nextStep = () => {
    if (stepLockRef.current) return;
    stepLockRef.current = true;

    if (phase === 0) {
      setMe(m => ({ ...m, reserve: m.reserve + 1 }));
    } else if (phase === 1) {
      // ★必ず1枚のみドロー（同じカードが2枚出ないように1回だけpop）
      setDeck(d => {
        const nd = [...d];
        if (nd.length) {
          const card = nd.pop();
          setHand(h => [...h, card]);
        }
        return nd;
      });
    } else if (phase === 2) {
      setMe(m => ({
        ...m,
        reserve: m.reserve + m.trash,
        trash: 0,
        zones: m.zones.map(z => (z ? { ...z, exhausted: z.card.type !== "spirit" } : z)),
      }));
      setMyAttackCount(0);
    }
    setPhase(p => Math.min(4, p + 1));

    // ロック解除
    setTimeout(() => { stepLockRef.current = false; }, 0);
  };

  const onHandClick = (i) => setSelectedHandIndex(prev => (prev === i ? null : i));

  const summonToZone = (zoneIdx) => {
    if (!canSummon || selectedHandIndex === null) return;
    if (me.zones[zoneIdx] !== null) return;
    const card = hand[selectedHandIndex];
    if (card.type === "magic") return;

    const reductions = getAvailableReductionsFromBoard(me.zones);
    const actualCost = calcActualCost(card, reductions);
    const needCores = card.levels?.[0]?.core ?? 0;
    const totalPay = actualCost + needCores;
    if (me.reserve < totalPay) { alert(`コア不足：必要${totalPay}（コスト${actualCost} + 初期コア${needCores}） / 手持ち${me.reserve}`); return; }

    setMe(m => ({
      ...m,
      reserve: m.reserve - totalPay,
      trash: m.trash + actualCost,
      zones: m.zones.map((z, i) => i===zoneIdx ? { card, cores: needCores, exhausted: card.type !== "spirit" } : z),
    }));
    setHand(h => { const nh=[...h]; nh.splice(selectedHandIndex,1); return nh; });
    setSelectedHandIndex(null);
  };

  // コア ±
  const addCore = (zoneIdx) => {
    if (!canSummon) return;
    const z = meRef.current.zones[zoneIdx]; if (!z) return;
    if (meRef.current.reserve <= 0) return;
    setMe(m => ({ ...m, reserve: m.reserve - 1, zones: m.zones.map((zz,i)=> (i===zoneIdx&&zz?{...zz, cores:(zz.cores||0)+1}:zz)) }));
  };
  const removeCore = (zoneIdx) => {
    if (!canSummon) return;
    const z = meRef.current.zones[zoneIdx]; if (!z || (z.cores||0)<=0) return;
    setMe(m => ({ ...m, reserve: m.reserve + 1, zones: m.zones.map((zz,i)=> (i===zoneIdx&&zz?{...zz, cores:(zz.cores||0)-1}:zz)) }));
  };

  // メイン：ダブルドロー（★必ず2枚だけ・二重発火ロック）
  const castMagicMain = (cardIndex) => {
    if (!canSummon) return;
    if (castLockRef.current) return;
    const card = hand[cardIndex];
    if (!card || card.type !== "magic") return;

    const reductions = getAvailableReductionsFromBoard(me.zones);
    const cost = calcActualCost(card, reductions);
    if (me.reserve < cost) { alert(`コア不足：必要${cost} / 手持ち${me.reserve}`); return; }

    if (card.id === "double-draw-001") {
      castLockRef.current = true;

      // 1) コスト支払い＋カードトラッシュへ
      setMe(m => ({ ...m, reserve:m.reserve - cost, trash:m.trash + cost, cTrash:[...m.cTrash, card] }));

      // 2) 手札からダブルドローを1回だけ抜く＆2枚だけ追加（★1回の setHand 内で）
      setDeck(d => {
        const nd = [...d];
        const draw1 = nd.length ? nd.pop() : null;
        const draw2 = nd.length ? nd.pop() : null;
        setHand(h => {
          const nh = [...h];
          nh.splice(cardIndex, 1);      // このダブルドローを取り除く
          if (draw1) nh.push(draw1);
          if (draw2) nh.push(draw2);
          return nh;
        });
        return nd;
      });

      // ロック解除
      setTimeout(() => { castLockRef.current = false; }, 0);
    }
  };

  // AIブロック（簡易）
  function aiChooseBlockFor(attackerBP, attackerSymbols, forced) {
    const ready = opRef.current.zones
      .map((z, i) => (z && !z.exhausted && z.card.type === "spirit" ? { i, bp: getBP(z) } : null))
      .filter(Boolean);
    if (ready.length === 0) return null;
    const killers = ready.filter(r => r.bp >= attackerBP).sort((a,b)=>a.bp-b.bp);
    if (killers.length > 0) return killers[0].i;
    if (!forced) {
      const lethal = attackerSymbols >= opRef.current.life;
      if (!lethal) return null;
    }
    return ready.sort((a,b)=>b.bp-a.bp)[0].i;
  }

  // 攻撃（プレイヤー → AI）
  const attackWith = async (zoneIdx) => {
    if (!canAttack || gameOver) return;
    const z = meRef.current.zones[zoneIdx]; if (!z || z.exhausted || z.card.type !== "spirit") return;

    const symbols = Math.max(0, z.card.symbolCount || 1);
    const atkBPOvBase = getAttackBP(z);
    const forced = mustForceBlock(z, opRef.current.zones);

    const blkIndex = aiChooseBlockFor(atkBPOvBase, symbols, forced);
    if (blkIndex === null) {
      applyUnblockedDamage("op", symbols, "me", zoneIdx);
      setMyAttackCount(c => c + 1);
      if (z.card.id === "siegwurm-001" && myAttackCount === 0 && hasDeityLv("me", 2)) {
        setMe(m => ({ ...m, zones: m.zones.map((zz, i) => (i === zoneIdx && zz ? { ...zz, exhausted: false } : zz)) }));
      }
      return;
    }

    // フラッシュ（攻撃/ブロックのカードとBPを見せる）
    const blkBPBase = getBP(opRef.current.zones[blkIndex]);
    const { atkBP, blkBP } = await runFlashWindow("me", zoneIdx, blkIndex, atkBPOvBase, blkBPBase);

    // バトル
    resolveBattle("me", zoneIdx, blkIndex, atkBP, blkBP);
    const wasFirst = (z.card.id === "siegwurm-001" && myAttackCount === 0 && hasDeityLv("me", 2));
    setMyAttackCount(c => c + 1);
    if (wasFirst) {
      const now = meRef.current.zones[zoneIdx];
      if (now) setMe(m => ({ ...m, zones: m.zones.map((zz, i) => (i === zoneIdx && zz ? { ...zz, exhausted: false } : zz)) }));
    }
  };

  const onZoneClick = (zoneIdx) => { if (!me.zones[zoneIdx]) summonToZone(zoneIdx); };

  /* ========== AIターン ========== */
  const enemyTurn = async () => {
    if (gameOver) return;
    const logs = [];

    // 0 コア
    setOp(o => ({ ...o, reserve: o.reserve + 1 }));

    // 1 ドロー（★1枚だけ）
    setOpDeck(d => {
      const nd=[...d];
      if (nd.length) {
        const card = nd.pop();
        setOpHand(h => [...h, card]);
      }
      return nd;
    });

    // 2 リフレッシュ
    setOp(o => ({
      ...o,
      reserve: o.reserve + o.trash,
      trash: 0,
      zones: o.zones.map(z => (z ? { ...z, exhausted: z.card.type !== "spirit" } : z)),
    }));

    // 3 メイン（召喚 or コア+1）
    let sim = {
      me: structuredClone(meRef.current),
      op: structuredClone({
        ...opRef.current,
        reserve: opRef.current.reserve + 1 + opRef.current.trash,
        trash: 0,
        zones: opRef.current.zones.map(z => (z ? { ...z, exhausted: z.card.type !== "spirit" } : z)),
      }),
      opHand: [...opHand, ...(opDeck[0] ? [opDeck[0]] : [])],
      opDeckCount: Math.max(0, opDeck.length - 1),
    };
    for (let i = 0; i < 20; i++) {
      const mv = chooseBestMainMove(sim);
      if (!mv) break;
      logs.push(mv.type === "SUMMON" ? `AI召喚: ゾーン${mv.zoneIndex + 1}` : `AIコア+1: ゾーン${mv.zoneIndex + 1}`);
      if (mv.type === "SUMMON") {
        const card = sim.opHand[mv.handIndex];
        const { totalPay, needCores, actualCost } = mv.pay;
        setOp(o => ({
          ...o,
          reserve: o.reserve - totalPay,
          trash: o.trash + actualCost,
          zones: o.zones.map((z, i) => i===mv.zoneIndex ? { card, cores: needCores, exhausted: card.type !== "spirit" } : z),
        }));
        setOpHand(h => { const nh=[...h]; nh.splice(mv.handIndex,1); return nh; });
      } else if (mv.type === "CORE_ADD") {
        setOp(o => ({ ...o, reserve:o.reserve-1, zones:o.zones.map((z,i)=>(i===mv.zoneIndex&&z?{...z, cores:(z.cores||0)+1}:z)) }));
      }
      sim = simulateMain(sim, mv);
    }

    // 4 アタック
    let opAttackCount = 0;
    for (let i = 0; i < 4; i++) {
      if (gameOver) break;
      const curr = opRef.current;
      const z = curr.zones[i];
      if (!z || z.exhausted || z.card.type !== "spirit") continue;

      const symbols = Math.max(0, z.card.symbolCount || 1);
      const atkBPOvBase = getAttackBP(z);
      const forced = mustForceBlock(z, meRef.current.zones);

      const readyDefs = meRef.current.zones.some(zz => zz && !zz.exhausted && zz.card.type === "spirit");
      if (!readyDefs) {
        applyUnblockedDamage("me", symbols, "op", i);
        logs.push(`AI攻撃: ゾーン${i + 1}→ノーブロック`);
        opAttackCount++;
        if (z.card.id === "siegwurm-001" && opAttackCount === 1 && hasDeityLv("op", 2)) {
          setOp(o => ({ ...o, zones: o.zones.map((zz, k) => (k === i && zz ? { ...zz, exhausted: false } : zz)) }));
        }
        continue;
      }

      // ブロック選択（人間）
      const choice = await new Promise((resolve) => {
        const attacker = z.card;
        setBlockPrompt({
          defender: "me",
          attackerSide: "op",
          attackerZone: i,
          attacker,
          attackerBP: atkBPOvBase,
          attackerSymbols: symbols,
          forced,
        });
        // クリック結果でresolveする
        const id = setInterval(() => {
          // resolveはボタン側で呼ぶのでここでは何もしない
          clearInterval(id);
        }, 1);
        // 保存
        blockResolverRef.current = resolve;
      });

      // 選択モーダルを閉じる
      setBlockPrompt(null);
      blockResolverRef.current = null;

      let decided = choice;
      if (forced && (!decided || decided.type === "none")) {
        const firstReady = meRef.current.zones.findIndex(zz => zz && !zz.exhausted && zz.card.type === "spirit");
        if (firstReady !== -1) decided = { type: "block", blocker: firstReady };
      }

      if (!decided || decided.type === "none") {
        applyUnblockedDamage("me", symbols, "op", i);
        logs.push(`AI攻撃: ゾーン${i + 1}→ブロックなし`);
        opAttackCount++;
        if (z.card.id === "siegwurm-001" && opAttackCount === 1 && hasDeityLv("op", 2)) {
          setOp(o => ({ ...o, zones: o.zones.map((zz, k) => (k === i && zz ? { ...zz, exhausted: false } : zz)) }));
        }
        continue;
      }

      // フラッシュ
      const blkBPBase = getBP(meRef.current.zones[decided.blocker]);
      const { atkBP, blkBP } = await runFlashWindow("op", i, decided.blocker, atkBPOvBase, blkBPBase);

      // バトル
      resolveBattle("op", i, decided.blocker, atkBP, blkBP);
      opAttackCount++;
      if (z.card.id === "siegwurm-001" && opAttackCount === 1 && hasDeityLv("op", 2)) {
        const now = opRef.current.zones[i];
        if (now) setOp(o => ({ ...o, zones: o.zones.map((zz, k) => (k === i && zz ? { ...zz, exhausted: false } : zz)) }));
      }
    }

    setAiLog(l => [...l, ...logs]);
    setPhase(0);
  };

  /* ========== ブロックUI用の解決器 ========= */
  const blockResolverRef = useRef(null);

  /* ========== UI（モーダルは最上面固定） ========== */
  const phaseName = ["①コア", "②ドロー", "③リフレッシュ", "④メイン", "⑤アタック"][phase];

  return (
    <>
      {/* === ブロック選択 === */}
      {blockPrompt && blockPrompt.defender === "me" && (
        <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,.5)", zIndex:2147483647, display:"flex", alignItems:"center", justifyContent:"center"}}>
          <div style={{background:"#111", borderRadius:16, padding:16, width:700, color:"#fff"}}>
            <div style={{fontWeight:700, fontSize:18, marginBottom:8}}>
              ブロック{blockPrompt.forced ? "（必須）" : ""}を選択
            </div>
            {/* 攻撃側の情報 */}
            <div style={{display:"grid", gridTemplateColumns:"120px 1fr", gap:12, alignItems:"center", marginBottom:12}}>
              <img src={blockPrompt.attacker?.img} alt={blockPrompt.attacker?.name} style={{width:120, height:168, objectFit:"cover", borderRadius:8, border:"2px solid #e11"}}/>
              <div>
                <div style={{fontSize:16, fontWeight:700}}>{blockPrompt.attacker?.name}</div>
                <div>BP {blockPrompt.attackerBP} / シンボル {blockPrompt.attackerSymbols}</div>
                <div style={{opacity:.7}}>攻撃中のカード</div>
              </div>
            </div>
            <div style={{fontSize:14, marginBottom:8}}>ブロックするスピリットを選んでください</div>
            <div style={{display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8}}>
              {me.zones.map((z, i) => {
                if (!z || z.exhausted || z.card.type !== "spirit") {
                  return <button key={i} className="btn" style={{opacity:.35}} disabled>{i+1}：不可</button>;
                }
                const info = levelFromCores(z.card, z.cores);
                return (
                  <button
                    key={i}
                    className="btn"
                    onClick={() => { const r = blockResolverRef.current; if (r) r({ type:"block", blocker:i }); }}
                    title={`${z.card.name} / Lv${info.lv} BP${info.bp}`}
                    style={{display:"flex",gap:8,alignItems:"center", justifyContent:"flex-start"}}
                  >
                    <img src={z.card.img} alt="" style={{width:60, height:84, objectFit:"cover", borderRadius:6}}/>
                    <div>
                      <div style={{fontWeight:700}}>{i+1}：{z.card.name}</div>
                      <div>Lv{info.lv} / BP {info.bp}</div>
                    </div>
                  </button>
                );
              })}
            </div>
            {!blockPrompt.forced && (
              <div style={{display:"flex",justifyContent:"flex-end",marginTop:12}}>
                <button className="btn" onClick={() => { const r = blockResolverRef.current; if (r) r({ type:"none" }); }}>
                  ブロックしない
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* === フラッシュ === */}
      {flashPrompt && (
        <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,.5)", zIndex:2147483647, display:"flex", alignItems:"center", justifyContent:"center"}}>
          <div style={{background:"#111", borderRadius:16, padding:16, width:720, color:"#fff"}}>
            <div style={{fontWeight:700, fontSize:18, marginBottom:8}}>フラッシュ</div>
            <div style={{display:"grid", gridTemplateColumns:"1fr 80px 1fr", alignItems:"center", gap:12, marginBottom:12}}>
              <div style={{display:"flex", gap:8}}>
                <img src={flashPrompt.attacker?.img} alt="" style={{width:90, height:126, objectFit:"cover", borderRadius:8}}/>
                <div>
                  <div style={{fontWeight:700}}>攻撃側：{flashPrompt.attacker?.name}</div>
                  <div>BP {flashPrompt.atkBP}</div>
                </div>
              </div>
              <div style={{textAlign:"center", fontWeight:700}}>VS</div>
              <div style={{display:"flex", gap:8}}>
                <img src={flashPrompt.blocker?.img} alt="" style={{width:90, height:126, objectFit:"cover", borderRadius:8}}/>
                <div>
                  <div style={{fontWeight:700}}>ブロック側：{flashPrompt.blocker?.name}</div>
                  <div>BP {flashPrompt.blkBP}</div>
                </div>
              </div>
            </div>
            <div style={{marginBottom:10}}>{flashPrompt.msg}</div>
            <div style={{display:"flex", gap:8, justifyContent:"flex-end"}}>
              <button className="btn" onClick={() => flashPrompt.onUse()}>使う（ダブルドロー）</button>
              <button className="btn" onClick={() => flashPrompt.onPass()}>使わない</button>
            </div>
          </div>
        </div>
      )}

      {/* === 霊峰のコア移動（★owner側の盤面に乗せるUI） === */}
      {coreMovePrompt && (
        <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,.5)", zIndex:2147483647, display:"flex", alignItems:"center", justifyContent:"center"}}>
          <div style={{background:"#111", borderRadius:16, padding:16, width:620, color:"#fff"}}>
            <div style={{fontWeight:700, fontSize:18, marginBottom:8}}>コア移動（{coreMovePrompt.cores}個）</div>
            <div style={{marginBottom:8, opacity:.8}}>移動先を選んでください（{coreMovePrompt.owner === "me" ? "自分" : "相手"}フィールド）</div>
            <div style={{display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8}}>
              {(coreMovePrompt.owner === "me" ? me.zones : op.zones).map((z, i) => {
                if (!z || z.card.type !== "spirit") return null;
                const info = levelFromCores(z.card, z.cores);
                return (
                  <button
                    key={i}
                    className="btn"
                    onClick={() => {
                      if (coreMovePrompt.owner === "me") {
                        setMe(m => ({ ...m, zones: m.zones.map((zz,k)=>(k===i&&zz?{...zz, cores:(zz.cores||0)+coreMovePrompt.cores}:zz)) }));
                      } else {
                        setOp(o => ({ ...o, zones: o.zones.map((zz,k)=>(k===i&&zz?{...zz, cores:(zz.cores||0)+coreMovePrompt.cores}:zz)) }));
                      }
                      setCoreMovePrompt(null);
                    }}
                  >
                    {coreMovePrompt.owner === "me" ? "自分" : "相手"}ゾーン{i + 1}に全て（{z.card.name} Lv{info.lv}）
                  </button>
                );
              })}
              <button className="btn" onClick={() => { moveCoresToReserve(coreMovePrompt.owner, coreMovePrompt.cores); setCoreMovePrompt(null); }}>
                リザーブへ戻す
              </button>
            </div>
          </div>
        </div>
      )}

      {/* === 勝敗 === */}
      {gameOver && (
        <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,.6)", zIndex:2147483647, display:"flex", alignItems:"center", justifyContent:"center"}}>
          <img src={gameOver === "win" ? WIN_IMG : LOSE_IMG} alt={gameOver === "win" ? "勝利" : "敗北"} style={{maxWidth:"70vw", maxHeight:"70vh", borderRadius:16, background:"#fff"}}/>
        </div>
      )}

      {/* === 盤面 === */}
      <div className="board">
        {/* 自分側 */}
        <section className="side my-side">
          <header className="hud hud-top">
            <span className="hud-item">フェーズ <b>{phaseName}</b></span>
            <span className="hud-item">LIFE <b>{me.life}</b></span>
            <span className="hud-item">RESERVE <b>{me.reserve}</b></span>
            <span className="hud-item">TRASH <b>{me.trash}</b></span>
            <span className="hud-item">CARD-TRASH <b>{me.cTrash.length}</b></span>
            <span className="spacer" />
            <button className="btn next-btn" onClick={nextStep} disabled={phase===4 || !!gameOver}>次のステップ</button>
            <button className="btn" onClick={enemyTurn} disabled={!!gameOver}>敵のターン</button>
          </header>

          <div className="field">
            {me.zones.map((z, i) => {
              if (!z) {
                const sel = selectedHandIndex !== null ? hand[selectedHandIndex] : null;
                const placeable = !!sel && sel.type !== "magic" && phase===3;
                return (
                  <div key={i} className={`zone ${placeable ? "placeable" : ""}`} onClick={() => onZoneClick(i)}>
                    <span>ゾーン{i + 1}</span>
                  </div>
                );
              }
              const info = levelFromCores(z.card, z.cores);
              return (
                <div key={i} className={`zone filled ${z.exhausted ? "attacked" : ""}`}>
                  <img src={z.card.img} alt={z.card.name} className="zone-card" />
                  <div className="zone-badge">{z.card.type.toUpperCase()} / Lv{info.lv} / BP {info.bp}</div>
                  {z.exhausted && <div className="zone-flag">疲労</div>}
                  <div className="zone-controls">
                    <button className="btn-small" onClick={() => removeCore(i)} disabled={phase!==3 || !!gameOver}>-</button>
                    <button className="btn-small" onClick={() => addCore(i)}    disabled={phase!==3 || !!gameOver}>+</button>
                    {z.card.type === "spirit" && (
                      <button
                        className={`btn-small warn ${z.exhausted ? "disabled" : ""}`}
                        onClick={() => attackWith(i)}
                        disabled={phase!==4 || !!z.exhausted || !!gameOver}
                        title={z.exhausted ? "疲労中" : "アタック"}
                      >
                        ATK
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>

          {/* 手札 */}
          <footer className="hand hand-bottom">
            {hand.length === 0 ? (
              <span>手札ゾーン</span>
            ) : (
              <div className="hand-cards" style={{ flexWrap: "nowrap" }}>
                {hand.map((card, idx) => (
                  <div key={`${card.id}-${idx}`} style={{ position: "relative", flex: "0 0 auto" }}>
                    <img
                      src={card.img}
                      alt={card.name}
                      className={`card-img ${selectedHandIndex === idx ? "selected" : ""}`}
                      onClick={() => onHandClick(idx)}
                      draggable={false}
                      title={card.name}
                      style={{ flex: "0 0 auto" }}
                    />
                    {card.type === "magic" && phase===3 && (
                      <button className="btn-small" style={{ position: "absolute", bottom: 6, left: 6 }} onClick={() => castMagicMain(idx)}>
                        使用（メイン）
                      </button>
                    )}
                  </div>
                ))}
              </div>
            )}
          </footer>
        </section>

        {/* 仕切り線 */}
        <div className="divider" />

        {/* 相手側 */}
        <section className="side op-side">
          <header className="hud hud-bottom">
            <span className="hud-item red">LIFE <b>{op.life}</b></span>
            <span className="hud-item red">RESERVE <b>{op.reserve}</b></span>
            <span className="hud-item red">TRASH <b>{op.trash}</b></span>
            <span className="hud-item red">CARD-TRASH <b>{op.cTrash.length}</b></span>
            <span className="spacer" />
            <span className="hud-item">敵手札 {opHand.length} 枚</span>
          </header>

          <div className="field">
            {op.zones.map((z, i) => {
              if (!z) return <div key={i} className="zone"><span>{i + 1}ゾーン</span></div>;
              const info = levelFromCores(z.card, z.cores);
              return (
                <div key={i} className={`zone filled ${z.exhausted ? "attacked" : ""}`}>
                  <img src={z.card.img} alt={z.card.name} className="zone-card" />
                  <div className="zone-badge">{z.card.type.toUpperCase()} / Lv{info.lv} / BP {info.bp}</div>
                  {z.exhausted && <div className="zone-flag">疲労</div>}
                </div>
              );
            })}
          </div>

          {/* AIログ */}
          {aiLog.length > 0 && (
            <div style={{ marginTop: 8, fontSize: 12, color: "#fff" }}>
              <div style={{ fontWeight: 700, marginBottom: 4 }}>AIログ</div>
              <ul style={{ margin: 0, paddingLeft: 16 }}>
                {aiLog.slice(-8).map((t, i) => <li key={i}>{t}</li>)}
              </ul>
            </div>
          )}
        </section>
      </div>
    </>
  );
}
